protocol EvictionPolicy { associatedtype Element; func pick(_ keys: [Element]) -> Element }
struct Lru: EvictionPolicy { func pick(_ keys: [String]) -> String { keys[0] } }

struct Cache<Element, Policy: EvictionPolicy> where Policy.Element == Element {
    let policy: Policy
    func victim(_ keys: [Element]) -> Element { policy.pick(keys) }
}
let c = Cache(policy: Lru())   // Policy inferred as Lru, checked against the protocol
